-- Write the existing SEO Virtual Assistant course.
-- Keep the course draft-only until a human reviewer approves the full curriculum.

update public.training_courses
set
  summary = 'Practical SEO support training covering search intent, keyword research, SERP analysis, on-page SEO, content briefs, internal linking, technical checks, Search Console analysis, QA, responsible AI, and client-ready reporting.',
  estimated_minutes = 300,
  status = 'draft',
  published_at = null,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '20000000-0000-4000-8000-000000000011';

update public.training_lessons
set
  content = '[{"type":"heading","text":"SEO work starts with how search systems discover, understand, and serve pages"},{"type":"paragraph","text":"An SEO Virtual Assistant supports the research, implementation, checking, and reporting work that helps useful pages become easier to discover and understand. The role is not to promise rankings. Search visibility depends on many factors outside a VA’s control, including competition, site quality, authority, technical health, content usefulness, search intent, and changes in search systems."},{"type":"heading","text":"Four stages you must keep separate"},{"type":"list","items":["Discovery or crawling: a search engine finds a URL through links, sitemaps, feeds, or other discovery paths.","Indexing: the search engine decides whether and how the page is stored and understood.","Ranking: an indexed page may be considered for a query and ordered against competing results.","Clicking: even a ranking page may receive few clicks if the result does not satisfy intent or the snippet is weak."]},{"type":"heading","text":"Search intent before keywords"},{"type":"paragraph","text":"The query tells you what the user typed. Intent describes what the user is actually trying to accomplish. Common intent patterns include learning, comparing, finding a specific site, evaluating a service, and taking an action such as booking, buying, downloading, or contacting."},{"type":"steps","items":["Read the query literally.","Check the current search results rather than guessing from the wording.","Identify which page types dominate: guides, service pages, category pages, product pages, local results, videos, tools, or mixed results.","Note whether the results answer a broad topic or a narrow task.","Match the recommended page type to the visible intent.","Record uncertainty when the SERP is mixed."]},{"type":"callout","title":"Do not confuse ranking with indexing","text":"A page can be indexed and still rank poorly. A page can also be discovered but excluded from the index. Report the exact condition you verified rather than saying a page is “not on Google” without evidence."},{"type":"scenario","title":"The page exists but gets no search traffic","text":"A client says a service page is live but receives no clicks. Build a diagnostic sequence that checks indexability, current rankings, queries, page intent, title and snippet quality, internal links, and competing pages before proposing a rewrite."},{"type":"heading","text":"Useful evidence sources"},{"type":"list","items":["Live-page inspection","Google Search Console performance and indexing reports","Crawler exports","XML sitemap and robots directives","Server or analytics data when available","Search results for representative queries","Approved keyword tools"]},{"type":"heading","text":"Key takeaway"},{"type":"paragraph","text":"Strong SEO support separates crawlability, indexability, rankings, and clicks. Start from the user’s intent and verified site evidence before recommending changes."}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000011';

update public.training_lessons
set
  content = '[{"type":"heading","text":"Keywords are signals of demand, not a command to create one page per phrase"},{"type":"paragraph","text":"SEO research often produces hundreds of similar phrases. A good VA groups them by intent, topic, entity, and page purpose so the site does not create thin pages that compete with each other."},{"type":"heading","text":"Think in clusters"},{"type":"list","items":["Primary intent: the main job the page must solve.","Supporting variants: close wording differences that can usually live on the same page.","Subtopics: questions or concerns that deserve sections inside the page.","Distinct intent: a different search task that may justify a separate page.","Entities: people, places, brands, products, services, concepts, or attributes search systems use to understand context."]},{"type":"heading","text":"How cannibalization actually appears"},{"type":"paragraph","text":"Cannibalization is not simply two pages containing the same word. It becomes a concern when multiple pages target substantially the same intent and search engines repeatedly switch between them, split signals, or rank the less appropriate URL."},{"type":"steps","items":["List the candidate URLs.","Compare their primary intent and target audience.","Review the queries and landing pages in Search Console.","Check whether both URLs rank for the same high-value terms.","Compare page purpose, content overlap, internal anchors, canonicals, and indexability.","Choose whether to consolidate, differentiate, redirect, canonicalize, or leave them alone."]},{"type":"callout","title":"Similarity is not automatically a problem","text":"A service page and a supporting guide may mention the same topic but serve different user needs. Do not merge pages simply because keyword tools show overlapping terms."},{"type":"scenario","title":"Three pages for the same service","text":"A site has /virtual-assistant-seo, /seo-va, and /hire-seo-assistant. Search Console shows all three receiving impressions for “SEO virtual assistant.” Decide what evidence you need before recommending consolidation and describe the safest canonical structure."},{"type":"heading","text":"Entity and topic coverage"},{"type":"paragraph","text":"Useful pages explain the relevant concepts, attributes, examples, and decisions around the topic. Do not force every related term into headings. Coverage should make the page more useful, not merely longer."},{"type":"heading","text":"Documentation standard"},{"type":"list","items":["Target topic and intent","Primary URL","Supporting terms","Potential competing URLs","Observed SERP page type","Recommended action","Evidence supporting the action"]}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000012';

update public.training_lessons
set
  content = '[{"type":"heading","text":"Keyword research is prioritization, not a volume contest"},{"type":"paragraph","text":"A keyword with large volume may be irrelevant to the client, too broad to convert, or dominated by a different page type. A smaller term can be more valuable when it closely matches the business, geography, service, and stage of the buyer journey."},{"type":"heading","text":"Minimum research fields"},{"type":"list","items":["Keyword or topic","Country or market","Search volume and its source","Keyword difficulty or competition metric and its source","Search intent","Current ranking URL if any","Current ranking position or range","Business relevance","Conversion potential","Existing page or new-page need","Notes from SERP review"]},{"type":"heading","text":"Prioritization framework"},{"type":"steps","items":["Confirm the market and language.","Remove obviously irrelevant phrases.","Group close variants by intent.","Map each cluster to an existing URL when one already fits.","Check live search results for the main terms.","Evaluate business relevance and likely page type.","Look for achievable opportunities such as relevant terms where the site already ranks on page two or three.","Separate quick on-page improvements from new-content opportunities."]},{"type":"callout","title":"Do not invent search volume","text":"If a keyword tool returns no data, record that honestly. Never fabricate volume, difficulty, CPC, or trend numbers to make a recommendation look stronger."},{"type":"heading","text":"Different tools measure differently"},{"type":"paragraph","text":"Volume, difficulty, and traffic estimates are modeled values. They can vary across tools and dates. Record the source and market so another person can reproduce the analysis."},{"type":"scenario","title":"High volume versus high relevance","text":"A law firm sees a 12,000-volume informational phrase and a 350-volume service-intent phrase. Explain how you would compare them using intent, page type, geography, business value, current authority, and conversion path instead of selecting the largest number."},{"type":"heading","text":"Opportunity tiers without false certainty"},{"type":"list","items":["Existing-page improvement","New supporting content","Commercial landing page gap","Internal-link opportunity","Content refresh","Longer-term authority topic"]}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000021';

update public.training_lessons
set
  content = '[{"type":"heading","text":"SERP analysis tells you what search intent looks like in practice"},{"type":"paragraph","text":"Before recommending a new page, inspect what currently ranks. The search results show the formats, angles, authority level, freshness, local context, and special result features that search systems consider useful for that query."},{"type":"heading","text":"What to record from the SERP"},{"type":"list","items":["Dominant page type","Commercial versus informational balance","Local-pack presence","Video, image, shopping, forum, or other SERP features","Recurring subtopics","Typical depth and format","Freshness signals","Major brands or authoritative publishers","Whether exact-match titles dominate or not"]},{"type":"heading","text":"Competitor-gap research"},{"type":"steps","items":["Choose real organic competitors for the target query, not just business competitors.","Review the sections and questions they cover.","Note useful information the client page is missing.","Identify weak or repetitive competitor content that creates an opportunity to be more useful.","Check whether the client already covers the topic elsewhere.","Recommend additions only when they improve the user’s task."]},{"type":"callout","title":"Do not copy competitor structure blindly","text":"Ranking pages are evidence of the current result set, not a template to duplicate. The goal is to understand user expectations and then produce something accurate, useful, and distinct."},{"type":"scenario","title":"Competitors all rank with guides","text":"The client wants a short sales landing page for a query where the first page is dominated by detailed comparison guides. Explain what this says about intent and how you would adjust the content recommendation."},{"type":"heading","text":"Gap types"},{"type":"list","items":["Missing question or subtopic","Missing comparison criteria","Missing local or industry detail","Weak proof or examples","Poor navigation or answer structure","Outdated information","Lack of original data or experience","No clear next step"]},{"type":"heading","text":"Evidence standard"},{"type":"paragraph","text":"Save the query, market, date, and representative ranking URLs. SERPs change. A recommendation should be tied to the conditions you actually reviewed."}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000022';

update public.training_lessons
set
  content = '[{"type":"heading","text":"Titles and headings should clarify the page, not repeat keywords mechanically"},{"type":"paragraph","text":"On-page SEO starts by making the page purpose obvious to users and search systems. The title, H1, headings, introduction, and supporting copy should all reinforce the same intent without sounding repetitive."},{"type":"heading","text":"Title tag workflow"},{"type":"steps","items":["Identify the page’s primary intent.","Use the most natural high-value topic wording.","Add an important qualifier such as location, audience, or service type when it helps users.","Avoid duplicate titles across pages.","Avoid stuffing multiple near-identical phrases.","Check how the title reads in search results."]},{"type":"heading","text":"Meta description workflow"},{"type":"paragraph","text":"A meta description is not a direct promise of ranking. It is a concise summary that can help users understand why the page is relevant. Search engines may rewrite it, so prioritize accuracy and usefulness over forcing every keyword into the copy."},{"type":"list","items":["Describe the actual page.","Match the user’s likely task.","Include a meaningful differentiator when true.","Avoid unsupported claims and fake urgency.","Do not duplicate the same description across many pages."]},{"type":"heading","text":"Heading hierarchy"},{"type":"list","items":["Use one clear page-level H1 in most standard page templates.","Use H2s for major sections.","Use H3s and deeper headings for real subsections.","Do not create headings only to insert keywords.","Make heading text understandable outside the SEO spreadsheet."]},{"type":"callout","title":"Do not rewrite a strong title just to hit an exact character count","text":"Length guidelines help avoid truncation, but relevance and clarity matter more than forcing every title into a rigid formula."},{"type":"scenario","title":"Service page with keyword stuffing","text":"A page title reads “SEO VA | SEO Virtual Assistant | Virtual Assistant SEO Services | Hire SEO VA.” Rewrite the direction so the title, H1, and description target the same intent naturally and explain why the original is weak."},{"type":"heading","text":"Final QA"},{"type":"steps","items":["Fetch or open the live page.","Verify the implemented title and description.","Check the H1 and heading order.","Confirm the canonical URL and indexability.","Check mobile rendering when the change affects visible headings or hero copy.","Record the final URL and evidence."]}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000031';

update public.training_lessons
set
  content = '[{"type":"heading","text":"A content brief should help a writer make decisions"},{"type":"paragraph","text":"A weak SEO brief is a list of keywords. A strong brief explains the audience, intent, page goal, required facts, useful sections, source expectations, internal links, and conversion path."},{"type":"heading","text":"Core brief fields"},{"type":"list","items":["Working title and page type","Primary audience","Search intent","Primary topic or cluster","Supporting questions","Recommended section structure","Required facts or source material","Internal links to include","Relevant service or product CTA","Examples, proof, screenshots, or original data available","Claims that require verification","Competitor or SERP observations"]},{"type":"heading","text":"Depth should be earned"},{"type":"paragraph","text":"Longer content is not automatically better. Include enough depth to answer the user’s task completely. Remove filler introductions, repeated definitions, generic transitions, and sections that exist only because a competitor used them."},{"type":"steps","items":["List the questions a user must answer before completing the task.","Group overlapping questions.","Order sections according to the user journey.","Mark where original examples or evidence would improve trust.","Identify content that belongs on another page.","Define a useful next step."]},{"type":"callout","title":"Do not turn every keyword into a heading","text":"If ten keyword variants mean the same thing, they may belong naturally in one well-written section rather than ten repetitive H2s."},{"type":"scenario","title":"The 3,000-word brief nobody needs","text":"A competitor article is 3,000 words, so a client asks for 4,000 words. The search task can be solved clearly in about 1,800 words with examples and a calculator. Explain how you would defend the shorter, more useful structure."},{"type":"heading","text":"Content QA"},{"type":"list","items":["Does the copy answer the intended search task?","Are facts current and sourced where needed?","Are examples specific rather than generic?","Are claims accurate?","Are internal links relevant?","Is any section duplicated elsewhere on the site?","Is the CTA appropriate for the page’s intent?","Is there obvious AI filler or unsupported wording?"]}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000032';

update public.training_lessons
set
  content = '[{"type":"heading","text":"Internal links should help users move to the next relevant page"},{"type":"paragraph","text":"Internal linking supports discovery, context, and site architecture. The best links are placed where a user would genuinely benefit from the destination, using anchor text that describes what they will find."},{"type":"heading","text":"Choose the source page first"},{"type":"steps","items":["Identify the destination page you want to support.","Find existing pages that are topically related.","Check whether the source page already mentions the concept naturally.","Confirm the destination is canonical, indexable, and live.","Choose the best sentence or section for the link.","Use a natural descriptive anchor.","Verify the live link after implementation."]},{"type":"heading","text":"Anchor text"},{"type":"list","items":["Describe the destination accurately.","Vary wording naturally when context changes.","Avoid generic “click here” when a descriptive phrase fits.","Avoid forcing exact-match keyword anchors everywhere.","Do not mislead users about what the destination contains."]},{"type":"callout","title":"Never recommend a link without checking the source page","text":"A spreadsheet can suggest a perfect anchor phrase that does not actually exist on the page. Verify the live source copy before telling a client to “link this exact text.”"},{"type":"heading","text":"Useful internal-link opportunities"},{"type":"list","items":["High-authority evergreen guides pointing to relevant service pages","Service pages linking to supporting guides","Hub pages connecting related subtopics","New articles linking to established canonical pages","Updated older pages linking to newer useful resources","Breadcrumbs and navigation where the information architecture supports them"]},{"type":"scenario","title":"A link matrix with 120 recommendations","text":"You receive a spreadsheet of proposed links. Build a QA process that checks excluded URLs, source-page relevance, exact anchor availability, destination status, duplication, self-links, and whether the link improves the reading experience."},{"type":"heading","text":"What not to do"},{"type":"list","items":["Do not add dozens of links simply because a keyword appears.","Do not link every instance of the same phrase.","Do not point multiple near-identical anchors to competing URLs without a clear reason.","Do not link to redirects when the final destination can be used directly.","Do not link to broken or non-indexable destinations unless there is a specific operational reason."]}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000041';

update public.training_lessons
set
  content = '[{"type":"heading","text":"Technical SEO triage begins with the exact URL state"},{"type":"paragraph","text":"A VA does not need to be the engineer who fixes every technical issue. The key skill is identifying the condition correctly, gathering evidence, understanding likely impact, and escalating with a reproducible description."},{"type":"heading","text":"Indexability checklist"},{"type":"list","items":["HTTP status code","Robots meta directives","X-Robots-Tag when relevant","Canonical tag","Robots.txt accessibility","XML sitemap inclusion","Internal-link discoverability","Rendered page availability","Search Console index status when accessible"]},{"type":"heading","text":"Canonical basics"},{"type":"paragraph","text":"A canonical tag signals the preferred URL among duplicate or very similar pages. It is a hint, not a guaranteed command. A canonical should usually point to a live, indexable, relevant version of the same content."},{"type":"heading","text":"Redirect basics"},{"type":"list","items":["301 or 308 redirects are commonly used for permanent URL moves.","302 or 307 redirects are commonly used for temporary moves.","Avoid redirect chains when a direct destination is available.","Check that the final destination returns the expected status.","Update internal links to point directly to the final URL where practical."]},{"type":"heading","text":"Sitemap basics"},{"type":"paragraph","text":"An XML sitemap should generally contain canonical, indexable URLs that the site wants search engines to discover. A sitemap is not a place to hide broken, redirected, duplicate, or noindex URLs."},{"type":"callout","title":"Do not diagnose from a crawler label alone","text":"A crawler may report “non-indexable canonical” or “blocked URL,” but you still need to inspect the URL, directives, destination, and site intent before recommending a fix."},{"type":"scenario","title":"Conflicting signals","text":"A URL returns 200, has a noindex tag, appears in the XML sitemap, and canonicals to itself. Explain the conflict, what you would verify with the site owner, and the possible fixes depending on whether the page should be indexed."},{"type":"heading","text":"Developer-ready issue report"},{"type":"steps","items":["State the affected URL or pattern.","State the observed behavior.","Include the evidence source.","Explain the desired behavior.","List reproduction steps.","Avoid guessing at root cause unless verified.","Retest after deployment."]}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000042';

update public.training_lessons
set
  content = '[{"type":"heading","text":"Search Console shows observed search performance, not a complete explanation of why it happened"},{"type":"paragraph","text":"Google Search Console can show queries, pages, countries, devices, clicks, impressions, CTR, average position, indexing information, and other search signals. A VA should use these metrics carefully and preserve the date and filter context."},{"type":"heading","text":"Core performance metrics"},{"type":"list","items":["Clicks: visits from Google Search recorded by Search Console.","Impressions: times a result was shown under Search Console’s measurement rules.","CTR: clicks divided by impressions.","Average position: an aggregated position metric that can vary by query, device, location, and result type."]},{"type":"heading","text":"Analysis workflow"},{"type":"steps","items":["Select the correct property.","Set the requested date range.","Set comparison periods when needed.","Confirm country, device, search type, query, and page filters.","Export the data when the task needs row-level analysis.","Separate brand and non-brand queries when useful.","Look for high-impression pages with low CTR.","Look for queries ranking near the first page that match strong business intent.","Check whether clicks changed because impressions changed, rankings changed, CTR changed, or all three.","Document the exact filter state in the report."]},{"type":"callout","title":"Do not compare different populations as if they are the same","text":"A global 3-month report should not be presented as evidence for current Philippines mobile performance. Match the time period, country, device, and search type to the decision being made."},{"type":"scenario","title":"High impressions, low clicks","text":"A page has 80,000 impressions, 450 clicks, and an average position of 8.9. Build the next analysis steps before deciding that the title alone is the problem."},{"type":"heading","text":"Useful segment questions"},{"type":"list","items":["Which queries generate the impressions?","Which countries and devices matter to the business?","Is the page ranking for the intended topic or accidental queries?","Did the SERP change?","Is there a competing page from the same site?","Does the title accurately match the visible intent?","Did seasonality change demand?"]},{"type":"heading","text":"Reporting standard"},{"type":"paragraph","text":"State what the data shows, what it does not prove, and what you recommend checking next. Avoid claiming that a specific edit caused an outcome unless the evidence supports that conclusion."}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000051';

update public.training_lessons
set
  content = '[{"type":"heading","text":"SEO QA closes the gap between recommendation and reality"},{"type":"paragraph","text":"A recommendation is not complete when it is written in a spreadsheet. The implementation must be checked on the live page, and the report should distinguish planned, implemented, verified, blocked, and rejected work."},{"type":"heading","text":"Pre-change QA"},{"type":"list","items":["Confirm the correct URL.","Capture the current title, description, H1, canonical, status, and indexability when relevant.","Check whether the issue already changed since the audit.","Confirm the proposed destination or replacement exists.","Check mobile and desktop when layout is affected.","Record screenshots or exports when useful."]},{"type":"heading","text":"Post-change validation"},{"type":"steps","items":["Fetch or open the production URL.","Verify the exact requested change.","Confirm no new redirect or canonical problem was introduced.","Check the visible page when user-facing copy changed.","Check structured data or headers when the change involves them.","Retest links.","Update the task status with evidence."]},{"type":"heading","text":"Client-facing status language"},{"type":"list","items":["Verified live: checked on production and confirmed.","Implemented, awaiting re-crawl: live change is present but search systems may not have reprocessed it.","Recommendation only: no implementation evidence yet.","Blocked: cannot proceed without access, development, or client decision.","Not reproducible: the reported issue is not currently present.","No change recommended: evidence does not support the proposed fix."]},{"type":"callout","title":"Never mark work complete because a ticket was closed","text":"If the deliverable requires a live-site fix, verify the live result. Tickets, pull requests, and CMS saves are implementation signals, not final proof."},{"type":"scenario","title":"The audit says fixed, but production disagrees","text":"A developer says the duplicate title issue is resolved. Your crawler export still shows the duplicates and the live page source contains the old title. Write the QA note and explain what evidence you would attach."},{"type":"heading","text":"Change logs and reporting"},{"type":"paragraph","text":"Record URL, issue, recommendation, owner, date changed, validation date, evidence, and next check. This creates a reliable history and makes later performance analysis much easier."}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000052';

update public.training_lessons
set
  content = '[{"type":"heading","text":"AI can accelerate SEO work, but it cannot replace verification"},{"type":"paragraph","text":"Use AI to help organize research, summarize exports, brainstorm structures, draft metadata, classify issues, and turn notes into clearer documentation. Every factual claim, number, URL state, source, and implementation result still needs verification."},{"type":"heading","text":"Good uses"},{"type":"list","items":["Cluster a provided keyword list by likely intent for human review.","Draft several title or description options from verified page content.","Summarize a crawler export you actually supplied.","Turn a confirmed issue list into developer-ready tickets.","Draft content-brief sections from verified SERP notes.","Rewrite repetitive reporting into concise client language.","Generate QA checklists from a known implementation plan."]},{"type":"heading","text":"Unsafe or unreliable uses"},{"type":"list","items":["Inventing keyword volume, traffic, difficulty, rankings, backlinks, or conversion data.","Claiming a live URL was checked when it was not.","Fabricating sources or citations.","Generating technical findings without access to the site or export.","Uploading confidential client data into an unapproved AI tool.","Publishing AI-written content without factual and brand review.","Presenting model guesses as crawler or Search Console evidence."]},{"type":"callout","title":"AI output is not audit evidence","text":"A model can explain what a canonical issue usually means, but it cannot prove that a specific page has that issue unless the relevant page data was actually provided and checked."},{"type":"heading","text":"Verification workflow"},{"type":"steps","items":["Define the SEO task.","Collect the real inputs.","Use AI only on those inputs when appropriate.","Review every recommendation.","Verify URLs and metrics against the source.","Remove invented or unsupported statements.","Record the source of truth in the final deliverable."]},{"type":"scenario","title":"AI says 46 pages have missing H1s","text":"You asked an AI tool to review a short site summary and it claims 46 pages are missing H1s. Explain why this is not usable evidence and describe the correct way to confirm the issue count."},{"type":"heading","text":"Privacy and client data"},{"type":"paragraph","text":"Follow the client’s approved tool policy. Do not paste private analytics exports, customer data, unpublished strategy, credentials, or proprietary documents into external AI tools without authorization."}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000061';

update public.training_lessons
set
  content = '[{"type":"heading","text":"Final composite SEO Virtual Assistant simulation"},{"type":"paragraph","text":"This simulation combines keyword research, intent mapping, on-page review, internal linking, technical triage, Search Console analysis, responsible AI, QA, and client communication. The fictional business is designed from common SEO workflows rather than any single client."},{"type":"scenario","title":"BrightPath Accounting","text":"BrightPath Accounting serves small businesses in Australia. The site has a bookkeeping service page, a payroll service page, a tax guide, and a newly published “small business bookkeeping” article. Search Console shows high impressions but low clicks for the bookkeeping service page. Two URLs alternate for “small business bookkeeping services.” A crawler export flags one noindex URL in the sitemap, a redirect chain, 14 duplicate meta descriptions, and several pages with weak internal linking. The client also provides a keyword export with volume and difficulty metrics."},{"type":"heading","text":"Part 1: Search demand and intent"},{"type":"steps","items":["Group the keyword export by intent.","Identify which clusters belong on existing pages.","Identify any genuine content gap.","Explain whether the two competing bookkeeping URLs appear to be cannibalizing each other.","State what additional evidence you need before consolidating anything."]},{"type":"heading","text":"Part 2: On-page and internal linking"},{"type":"list","items":["Draft a stronger title and meta description for the bookkeeping service page.","Propose a clean H1 and section structure.","Choose at least three relevant internal-link opportunities.","Write natural anchor-text recommendations.","Explain which duplicate meta descriptions deserve unique rewrites and which may be lower priority."]},{"type":"heading","text":"Part 3: Technical triage"},{"type":"steps","items":["Document the noindex-in-sitemap conflict.","Map the redirect chain to its final destination.","State the recommended correction.","Identify which issue requires developer support.","Define the exact post-fix validation checks."]},{"type":"heading","text":"Part 4: Search Console analysis"},{"type":"list","items":["Explain the high-impression, low-click condition without assuming the cause.","Segment the relevant queries.","Compare date periods correctly.","Identify whether CTR, average position, impressions, or query mix changed.","Separate observations from hypotheses."]},{"type":"heading","text":"Part 5: Client-ready handoff"},{"type":"steps","items":["Create a prioritized issue table.","Mark each item as evidence, recommendation, or open question.","Define owner and next action.","State what can be implemented immediately and what needs approval.","Write a short client summary with no exaggerated ranking promises."]},{"type":"callout","title":"Assessment standard","text":"A strong submission uses real evidence, preserves the difference between observation and inference, avoids keyword stuffing, does not invent metrics, and gives another person enough detail to implement and verify the work."}]'::jsonb,
  is_published = false,
  last_reviewed_at = null,
  reviewed_by = null,
  content_version = greatest(content_version, 1),
  updated_at = now()
where id = '22000011-0000-4000-8000-000000000062';

update public.training_assessments
set
  instructions = 'Complete the BrightPath Accounting composite SEO support simulation. Use the supplied keyword, Search Console, crawler, and page evidence to map intent, identify possible cannibalization, recommend on-page and internal-link improvements, triage technical issues, and produce a client-ready handoff. Separate verified evidence from assumptions, do not invent metrics, and define how each implemented change should be validated.',
  is_published = false,
  updated_at = now()
where id = '23000000-0000-4000-8000-000000000011';
